메뉴판 = {"김밥": 3000, "라면": 4000, "떡볶이": 3500, "주먹밥": 1500}
돈 = int(input("가진 돈: "))
수 = 0
for 메뉴, 값 in 메뉴판.items():
    if 값 <= 돈:
        print(f"{메뉴} {값}원")
        수 += 1
print(f"살 수 있는 것 {수}가지")

낱말들 = input("문장: ").split()
for 낱말 in sorted(set(낱말들)):
    print(f"{낱말} {낱말들.count(낱말)}")
